const input=document.querySelector('#fileInput'),zone=document.querySelector('#dropZone'),preview=document.querySelector('#preview'),browse=document.querySelector('#browseButton'),analyze=document.querySelector('#analyzeButton'),notice=document.querySelector('#notice'),promptInput=document.querySelector('#promptInput'),apiInput=document.querySelector('#apiInput'),emptyState=document.querySelector('#emptyState'),uploadMode=document.querySelector('#uploadMode'),drawMode=document.querySelector('#drawMode'),uploadState=document.querySelector('#uploadState'),drawState=document.querySelector('#drawState'),canvas=document.querySelector('#sketchCanvas'),clearCanvas=document.querySelector('#clearCanvas'),useCanvas=document.querySelector('#useCanvas'),demoModel=document.querySelector('#demoModel'),stageId=document.querySelector('.stage-id'),modelDownload=document.querySelector('.model-download'),compareToggle=document.querySelector('#compareToggle'),compareImage=document.querySelector('#compareImage'),resetView=document.querySelector('#resetView'),fullscreenView=document.querySelector('#fullscreenView'),viewerFrame=document.querySelector('#viewerFrame'),vertexCount=document.querySelector('#vertexCount'),faceCount=document.querySelector('#faceCount'),generationTime=document.querySelector('#generationTime');
const examples={revolver:{model:'assets/demo-revolver.glb',sketch:'assets/demo-revolver-sketch.jpg',title:'Revolver study',vertices:9267,faces:13928},cup:{model:'assets/demo-cup.glb',sketch:'assets/demo-cup-sketch.avif',title:'Cup study',vertices:17451,faces:30600},raw:{model:'assets/revolver_from_raw_sketch.glb',sketch:'assets/demo-revolver-sketch.jpg',title:'Raw-sketch study',vertices:13926,faces:22512}};
let objectUrl='',drawing=false,lastPoint=null;const context=canvas.getContext('2d');
function resetCanvas(){context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.strokeStyle='#18201f';context.lineWidth=4;context.lineCap='round';context.lineJoin='round'}
function resetViewer(){compareImage.hidden=true;demoModel.hidden=false;compareToggle.textContent='See sketch';demoModel.cameraOrbit='0deg 75deg 105%';demoModel.cameraTarget='auto auto auto';demoModel.jumpCameraToGoal?.()}
function setMeshDetails(vertices,faces,time='—'){vertexCount.textContent=Number(vertices).toLocaleString();faceCount.textContent=Number(faces).toLocaleString();generationTime.textContent=time}
function showExample(key){const example=examples[key];demoModel.setAttribute('src',example.model);compareImage.src=example.sketch;compareToggle.disabled=false;modelDownload.href=example.model;modelDownload.hidden=false;modelDownload.setAttribute('download',`${key}-sf3d.glb`);stageId.textContent=example.title;setMeshDetails(example.vertices,example.faces);resetViewer();document.querySelectorAll('.example-card').forEach(card=>card.classList.toggle('active',card.dataset.example===key));notice.textContent=`Viewing the saved ${example.title.toLowerCase()}. Drag it to inspect the 3D result.`}
resetCanvas();customElements.whenDefined('model-viewer').then(()=>showExample('revolver'));
function showMode(mode){const isDraw=mode==='draw';drawMode.classList.toggle('active',isDraw);uploadMode.classList.toggle('active',!isDraw);drawState.hidden=!isDraw;uploadState.hidden=isDraw}uploadMode.addEventListener('click',()=>showMode('upload'));drawMode.addEventListener('click',()=>showMode('draw'));
function acceptSource(url){if(objectUrl.startsWith('blob:'))URL.revokeObjectURL(objectUrl);objectUrl=url;preview.src=url;preview.hidden=false;compareImage.src=url;compareImage.hidden=true;compareToggle.disabled=false;compareToggle.textContent='See sketch';emptyState.hidden=true;analyze.disabled=false;notice.textContent='That is a great start. Connect Live mode when you are ready to generate a new model.'}function setFile(file){if(!file||!file.type.startsWith('image/'))return;acceptSource(URL.createObjectURL(file))}browse.addEventListener('click',()=>input.click());input.addEventListener('change',()=>setFile(input.files[0]));['dragenter','dragover'].forEach(event=>zone.addEventListener(event,entry=>{entry.preventDefault();zone.classList.add('drag')}));['dragleave','drop'].forEach(event=>zone.addEventListener(event,entry=>{entry.preventDefault();zone.classList.remove('drag')}));zone.addEventListener('drop',event=>setFile(event.dataTransfer.files[0]));
function point(event){const rect=canvas.getBoundingClientRect();return{x:(event.clientX-rect.left)*canvas.width/rect.width,y:(event.clientY-rect.top)*canvas.height/rect.height}}canvas.addEventListener('pointerdown',event=>{drawing=true;lastPoint=point(event);canvas.setPointerCapture(event.pointerId)});canvas.addEventListener('pointermove',event=>{if(!drawing)return;const next=point(event);context.beginPath();context.moveTo(lastPoint.x,lastPoint.y);context.lineTo(next.x,next.y);context.stroke();lastPoint=next});canvas.addEventListener('pointerup',()=>{drawing=false;lastPoint=null});canvas.addEventListener('pointercancel',()=>{drawing=false;lastPoint=null});clearCanvas.addEventListener('click',resetCanvas);useCanvas.addEventListener('click',()=>acceptSource(canvas.toDataURL('image/png')));
compareToggle.addEventListener('click',()=>{const showSketch=compareImage.hidden;compareImage.hidden=!showSketch;demoModel.hidden=showSketch;compareToggle.textContent=showSketch?'See 3D':'See sketch'});resetView.addEventListener('click',resetViewer);fullscreenView.addEventListener('click',()=>{if(document.fullscreenElement)document.exitFullscreen();else viewerFrame.requestFullscreen?.()});document.querySelectorAll('.example-card').forEach(card=>card.addEventListener('click',()=>showExample(card.dataset.example)));
apiInput.value=localStorage.getItem('sketch2shape-api-url')||'';apiInput.addEventListener('change',()=>localStorage.setItem('sketch2shape-api-url',apiInput.value.trim()));
analyze.addEventListener('click',async()=>{const apiUrl=apiInput.value.trim().replace(/\/$/,''),prompt=promptInput.value.trim(),stages=[...document.querySelectorAll('#stages li')];if(!apiUrl){notice.textContent='Live generation needs the GPU service. Explore the saved studies below, or add an active endpoint in Live mode.';document.querySelector('.connection').open=true;apiInput.focus();return}try{new URL(apiUrl)}catch{notice.textContent='That generation link is not quite right.';document.querySelector('.connection').open=true;apiInput.focus();return}analyze.disabled=true;analyze.innerHTML='Giving it shape <b>…</b>';notice.textContent='Your line is finding its way into a new dimension.';stages.forEach((stage,index)=>{stage.classList.toggle('active',index<3);stage.querySelector('em').textContent=index===0?'Here':index===1?'Growing':index===2?'Almost':'—'});const startedAt=performance.now();try{const imageBlob=await fetch(objectUrl).then(response=>response.blob()),form=new FormData();form.append('image',imageBlob,'sketch.png');form.append('prompt',prompt);const response=await fetch(`${apiUrl}/v1/generate`,{method:'POST',body:form});const payload=await response.json();if(!response.ok)throw new Error(payload.detail||'Generation failed.');const glbUrl=new URL(payload.glb_url,`${apiUrl}/`).href;demoModel.src=glbUrl;modelDownload.href=glbUrl;modelDownload.hidden=false;modelDownload.setAttribute('download','sketch2shape-output.glb');stageId.textContent='Your new model';setMeshDetails(payload.vertices,payload.faces,Math.max(1,Math.round((performance.now()-startedAt)/1000)));stages.forEach(stage=>{stage.classList.add('active');stage.querySelector('em').textContent='Done'});resetViewer();notice.textContent='There it is. Take it for a spin, then keep it.'}catch(error){notice.textContent=`We could not finish this one: ${error.message}`;stages.forEach((stage,index)=>{if(index>0){stage.classList.remove('active');stage.querySelector('em').textContent='—'}})}finally{analyze.disabled=false;analyze.innerHTML='Shape my idea <b>→</b>'}});
